package com.healthskillconnect.service;
import com.healthskillconnect.data.JsonDataLoader;import com.healthskillconnect.model.AppUser;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.util.*;import java.util.concurrent.CopyOnWriteArrayList;import java.util.concurrent.atomic.AtomicLong;import java.util.regex.Pattern;
@Service public class UserService {private final List<AppUser> users;private final PasswordEncoder encoder;private final AtomicLong ids=new AtomicLong(100);private static final Pattern PASS=Pattern.compile("^(?=.*[a-z])(?=.*[A-Z])(?=.*\\d)(?=.*[^A-Za-z0-9]).{8,}$");public UserService(JsonDataLoader data,PasswordEncoder encoder){this.users=new CopyOnWriteArrayList<>(data.users);this.encoder=encoder;for(AppUser u:users){String p=u.password;u.passwordHash=encoder.encode(p==null||p.isBlank()?"DemoPass123!":p);u.password=null;}}
 public AppUser byEmail(String email){return users.stream().filter(u->u.email.equalsIgnoreCase(email)).findFirst().orElse(null);}public AppUser byId(String id){return users.stream().filter(u->u.id.equals(id)).findFirst().orElse(null);}public boolean matches(AppUser u,String password){return u!=null&&encoder.matches(password,u.passwordHash);}public AppUser register(String name,String email,String password,String spec,String level,String location){if(byEmail(email)!=null)throw new IllegalArgumentException("An account with this email already exists.");if(!PASS.matcher(password).matches())throw new IllegalArgumentException("Password must be 8+ characters and include uppercase, lowercase, number, and special character.");AppUser u=new AppUser();u.id="user-"+ids.incrementAndGet();u.fullName=name.trim();u.email=email.trim().toLowerCase();u.role="STUDENT";u.specialization=spec;u.experienceLevel=level;u.location=location;u.avatarInitials=Arrays.stream(name.trim().split("\\s+")).limit(2).map(s->s.substring(0,1).toUpperCase()).reduce("",String::concat);u.passwordHash=encoder.encode(password);u.skills=new ArrayList<>();u.learningInterests=new ArrayList<>();users.add(u);return u;}public List<AppUser> all(){return List.copyOf(users);}public List<AppUser> role(String role){return users.stream().filter(u->u.role.equals(role)).toList();}public void changeRole(String id,String role){if(!List.of("STUDENT","MENTOR","ADMIN").contains(role))throw new IllegalArgumentException("Unsupported role.");AppUser u=byId(id);if(u==null)throw new NoSuchElementException("User not found.");u.role=role;}}
